# Let's search for broader food quality/taste complaints using terms like "gross", "nasty", "yuck", "inedible"
# and also "food" combined with negative sentiment words
food_taste_terms = ['gross', 'nasty', 'yuck', 'inedible', 'unappetizing', 'revolting', 'flavorless', 'bland']

food_taste_complaints = collections.defaultdict(list)

for row in dataset:
    dialog_lower = row['dialog'].lower()
    for term in food_taste_terms:
        if term in dialog_lower:
            # Check if it's related to food
            sentences = row['dialog'].split('\n')
            for s in sentences:
                if term in s.lower() and any(fw in s.lower() for fw in ['food', 'meal', 'eat', 'snack', 'catering']):
                    food_taste_complaints[row['company_id']].append((row['dialog_id'], s.strip()[:300]))

print("Food taste complaints with broader terms:")
for company, complaints in food_taste_complaints.items():
    print(f"\n{company}:")
    for dialog_id, text in complaints:
        print(f"  [{dialog_id}]: {text}")

if not food_taste_complaints:
    print("No additional food taste complaints found with broader terms.")

# Also let's check for "food" + negative adjective combinations
print("\n\n=== Checking 'food' with quality adjectives ===")
quality_terms = ['terrible food', 'horrible food', 'awful food', 'bad food', 'disgusting food', 
                 'gross food', 'nasty food', 'worst food', 'food was terrible', 'food was horrible',
                 'food was awful', 'food was bad', 'food was disgusting', 'food tasted', 'meal was terrible',
                 'meal was horrible', 'meal was awful', 'meal was bad', 'meal was disgusting', 'meal tasted']

food_quality_by_company = collections.defaultdict(list)
for row in dataset:
    dialog_lower = row['dialog'].lower()
    for term in quality_terms:
        if term in dialog_lower:
            sentences = row['dialog'].split('\n')
            for s in sentences:
                if term in s.lower():
                    food_quality_by_company[row['company_id']].append((row['dialog_id'], term, s.strip()[:300]))

for company, items in food_quality_by_company.items():
    print(f"\n{company}:")
    for dialog_id, term, text in items:
        print(f"  [{dialog_id}] ({term}): {text}")

if not food_quality_by_company:
    print("No food quality complaints found.")
